def parser(log: str) -> dict[str, str]:
    import re
    import json

    results: dict[str, str] = {}

    def set_status(name: str, status: str):
        prev = results.get(name)
        if status == "fail":
            results[name] = "fail"
        elif prev is None:
            results[name] = status
        elif prev == "fail":
            results[name] = "fail"
        elif prev != status:
            results[name] = "skip" if status == "skip" else prev

    # Extract the main JSON block by matching braces around the "stats" key
    def extract_json_block(s: str):
        idx = s.find('"stats"')
        if idx == -1:
            # fallback to "tests" if "stats" not found
            idx = s.find('"tests"')
            if idx == -1:
                return None
        start = s.rfind('{', 0, idx)
        if start == -1:
            return None
        brace = 0
        in_str = False
        esc = False
        end = None
        for i in range(start, len(s)):
            ch = s[i]
            if in_str:
                if esc:
                    esc = False
                elif ch == '\\':
                    esc = True
                elif ch == '"':
                    in_str = False
            else:
                if ch == '"':
                    in_str = True
                elif ch == '{':
                    brace += 1
                elif ch == '}':
                    brace -= 1
                    if brace == 0:
                        end = i
                        break
        if end is None:
            return None
        block = s[start:end + 1]
        try:
            return json.loads(block)
        except Exception:
            return None

    obj = extract_json_block(log)

    if obj:
        for t in obj.get("passes", []):
            name = t.get("fullTitle")
            if name:
                set_status(name, "pass")
        for t in obj.get("failures", []):
            name = t.get("fullTitle")
            if name:
                set_status(name, "fail")
        for t in obj.get("pending", []):
            name = t.get("fullTitle")
            if name:
                set_status(name, "skip")
        for t in obj.get("tests", []):
            name = t.get("fullTitle")
            if not name:
                continue
            if t.get("pending"):
                set_status(name, "skip")
                continue
            err = t.get("err", {})
            if isinstance(err, dict) and len(err) == 0:
                set_status(name, "pass")
            else:
                msg = err.get("message") if isinstance(err, dict) else None
                if msg:
                    set_status(name, "fail")
                else:
                    set_status(name, results.get(name, "pass"))
    else:
        # Fallback regex parsing for arrays if JSON couldn't be loaded
        def extract_from_array(label: str, status: str):
            m = re.search(rf'"{label}"\s*:\s*\[\s*(.*?)\s*\]', log, re.S)
            if not m:
                return
            block = m.group(1)
            for ft in re.findall(r'"fullTitle"\s*:\s*"([^"]+)"', block):
                set_status(ft, status)

        extract_from_array("passes", "pass")
        extract_from_array("failures", "fail")
        extract_from_array("pending", "skip")

        m = re.search(r'"tests"\s*:\s*\[\s*(.*?)\s*\]', log, re.S)
        if m:
            block = m.group(1)
            objs = re.findall(r'\{.*?\}', block, re.S)
            for obj_txt in objs:
                ftm = re.search(r'"fullTitle"\s*:\s*"([^"]+)"', obj_txt)
                if not ftm:
                    continue
                name = ftm.group(1)
                pm = re.search(r'"pending"\s*:\s*(true|false)', obj_txt, re.I)
                if pm and pm.group(1).lower() == "true":
                    set_status(name, "skip")
                    continue
                em = re.search(r'"err"\s*:\s*\{(.*?)\}', obj_txt, re.S)
                if em:
                    inner = em.group(1).strip()
                    if inner:
                        set_status(name, "fail")
                    else:
                        set_status(name, "pass")
                else:
                    set_status(name, "pass")

    return results
